import json
import os
import sys
from typing import Any, Dict

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from backend.common.models.match_suggestion import MatchSuggestions  # noqa: E402

OUTPUT_DIR = os.path.join(
    os.path.dirname(__file__), "..", "pwa", "app", "api", "firebase"
)
FILENAME = "matchSuggestions.schema.gen.ts"
CONST_NAME = "matchSuggestionsSchema"


def render(schema: Dict[str, Any]) -> str:
    body = json.dumps(schema, indent=2, sort_keys=True)
    return (
        "// This file is auto-generated by ops/export_match_suggestion_schema.py\n"
        "\n"
        f"export const {CONST_NAME} = {body} as const;\n"
    )


def main() -> None:
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    path = os.path.join(OUTPUT_DIR, FILENAME)
    with open(path, "w") as f:
        f.write(render(MatchSuggestions.model_json_schema()))
    print(f"wrote {os.path.relpath(path)}")


if __name__ == "__main__":
    main()
